// Cada 'Avaliar X' faz o mesmo trabalho: junta o que o HTTP Request devolveu com
// o servico/url/started_em que o Set correspondente guardou, e decide se está ok.
// O item que sai daqui é autossuficiente — os nós depois do Merge não precisam mais
// saber de qual dos quatro serviços ele veio.

const dados = $('Serviço: n8n (local)').item.json;
const resp = $json;

const erro = resp.error;
const statusHttp = resp.statusCode ?? null;
const ok = !erro && statusHttp >= 200 && statusHttp < 300;
const tempoRespostaMs = Math.max(0, Date.now() - Date.parse(dados.started_em));

let motivo = null;
if (erro) motivo = String(erro.message || erro).slice(0, 300);
else if (!ok) motivo = `HTTP ${statusHttp}`;

return {
  json: {
    servico: dados.servico,
    url: dados.url,
    ok,
    status_http: statusHttp,
    tempo_resposta_ms: tempoRespostaMs,
    motivo,
  },
};

