// Junta o resultado desta consulta (ok_anterior) com os dados da checagem atual,
// que ficaram no nó Juntar checagens — o Postgres substituiu o $json todo.
const atual = $('Juntar checagens').item.json;
const okAnterior = $json.ok_anterior;

const primeiraChecagem = okAnterior === null || okAnterior === undefined;
const mudouEstado = !primeiraChecagem && okAnterior !== atual.ok;

return {
  json: {
    ...atual,
    ok_anterior: okAnterior,
    primeira_checagem: primeiraChecagem,
    mudou_estado: mudouEstado,
  },
};

const linhas = $input.all().map(i => i.json);

if (linhas.length === 0) {
  return [{ json: { texto: '📊 **Relatório de disponibilidade — últimas 24h**\n\nNenhuma checagem registrada ainda.' } }];
}

const emoji = (pct) => (pct >= 99.5 ? '🟢' : pct >= 95 ? '🟡' : '🔴');

const partes = linhas.map((l) => {
  const pct = Number(l.disponibilidade_pct);
  const tempo = l.tempo_medio_ms != null ? `${l.tempo_medio_ms} ms` : 'sem dado';
  const quedas = Number(l.quedas) > 0 ? ` · ${l.quedas} queda(s)` : '';
  return `${emoji(pct)} **${l.servico}**: ${pct}% (${l.checagens_ok}/${l.total_checagens}) · resposta média ${tempo}${quedas}`;
});

const texto = '📊 **Relatório de disponibilidade — últimas 24h**\n\n' + partes.join('\n');

return [{ json: { texto } }];

// O insert do Postgres recusa o item inteiro se houver um campo sem coluna
// correspondente (ok_anterior, primeira_checagem, mudou_estado). Este nó entrega
// só as 6 colunas da tabela; o item completo segue pelo outro ramo, até os IF.
return {
  json: {
    servico: $json.servico,
    url: $json.url,
    ok: $json.ok,
    status_http: $json.status_http,
    tempo_resposta_ms: $json.tempo_resposta_ms,
    motivo: $json.motivo,
  },
};
